package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Val;

/** Swaps the person with the one above or below them in the list. Refused: the top row moving up,
 *  or the bottom row down. */
public class MovePerson {
    public void move(@Val Move move, @Val Person person, People people) throws InvalidSheetRequestException {
        if (!people.move(person, move.up()))
            throw new InvalidSheetRequestException(person.getName() + " is already " + (move.up() ? "first" : "last"));
        move.position()[0] = people.positionOf(person);
    }
}
EOF
